/**
 * Seed data for the Society Intelligence Network.
 *
 * Used as the data source when there is no database configured (see
 * `db.ts#hasDb`). Seed universities are the five targets; seed societies are a
 * small high-quality set so the admin engine and `/network` directory look like
 * a real product out of the box. Seed sources cover the five SU directories plus
 * the LSN CRM and existing-site placeholders (spec §6.1).
 *
 * IDs/slugs are stable strings — unique within this in-memory dataset only
 * (real UUIDs are generated by Postgres in DB mode).
 */

import { normaliseSocietyName } from "./normalise";
import type {
    Society,
    SocietySource,
    University,
} from "./types";
import { TARGET_UNIVERSITIES } from "./universities";

function daysFromNow(n: number): string {
    const d = new Date();
    d.setDate(d.getDate() + n);
    return d.toISOString();
}
const daysAgo = (n: number): string => daysFromNow(-n);

// --- Universities ---------------------------------------------------------

export function buildSeedUniversities(): University[] {
    const ts = daysAgo(120);
    return TARGET_UNIVERSITIES.map((u) => ({
        ...u,
        createdAt: ts,
        updatedAt: ts,
    }));
}

// --- Societies ------------------------------------------------------------

type SeedSociety = Omit<
    Society,
    | "normalisedName"
    | "createdAt"
    | "updatedAt"
    | "publishedAt"
    | "universityName"
    | "universityShortName"
> & { ageDays: number };

const uniName = (id: string) =>
    TARGET_UNIVERSITIES.find((u) => u.id === id)!.name;
const uniShort = (id: string) =>
    TARGET_UNIVERSITIES.find((u) => u.id === id)!.shortName;

