export function buildSeedSocieties(): Society[] {
    return SEED.map((s) => {
        const { ageDays, ...rest } = s;
        return {
            ...rest,
            universityName: uniName(s.universityId),
            universityShortName: uniShort(s.universityId),
            normalisedName: normaliseSocietyName(s.name),
            createdAt: daysAgo(ageDays),
            updatedAt: daysAgo(Math.max(0, ageDays - 2)),
            publishedAt:
                s.status === "published" ? daysAgo(Math.max(0, ageDays - 1)) : null,
        };
    });
}

// --- Sources (registry seed, spec §6.1) -----------------------------------

type SeedSource = Omit<SocietySource, "createdAt" | "updatedAt">;

export function buildSeedSources(): SocietySource[] {
    const ts = daysAgo(120);
    const directories: SeedSource[] = TARGET_UNIVERSITIES.map((u) => ({
        id: `src-seed-${u.id}`,
        societyId: null,
        universityId: u.id,
        sourceType: "su_directory",
        sourceName: `${u.shortName} Students' Union — societies directory`,
        sourceUrl: u.societyDirectoryUrl ?? null,
        rawTitle: null,
        rawText: null,
        rawHtml: null,
        extractedJson: null,
        trustLevel: "high",
        confidenceScore: 95,
        lastFetchedAt: null,
        fetchStatus: "new",
        errorMessage: null,
    }));

    const others: SeedSource[] = [
        {
            id: "src-seed-lsn-crm",
            societyId: null,
            universityId: null,
            sourceType: "lsn_crm",
            sourceName: "LSN SOC outreach CRM (uploaded spreadsheet)",
            sourceUrl: null,
            rawTitle: null,
            rawText: null,
            rawHtml: null,
            extractedJson: null,
            trustLevel: "medium",
            confidenceScore: 70,
            lastFetchedAt: null,
            fetchStatus: "new",
            errorMessage: null,
        },
        {
            id: "src-seed-lsn-site",
            societyId: null,
            universityId: null,
            sourceType: "lsn_existing_site",
            sourceName: "Existing londonstudentnetwork.com society pages",
            sourceUrl: "https://www.londonstudentnetwork.com/societies",
            rawTitle: null,
            rawText: null,
            rawHtml: null,
            extractedJson: null,
            trustLevel: "medium",
            confidenceScore: 75,
            lastFetchedAt: null,
            fetchStatus: "new",
            errorMessage: null,
        },
    ];

    return [...directories, ...others].map((s) => ({
        ...s,
        createdAt: ts,
        updatedAt: ts,
    }));
}
